import{_ as t,o as i,c as n,aj as a}from"./chunks/framework.C6uXqnaX.js";const b=JSON.parse('{"title":"Debugging tests","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/testing/debugging.md","filePath":"en/guide/testing/debugging.md"}'),s={name:"en/guide/testing/debugging.md"};function o(g,e,r,d,u,l){return i(),n("div",null,e[0]||(e[0]=[a('<h1 id="debugging-tests" tabindex="-1">Debugging tests <a class="header-anchor" href="#debugging-tests" aria-label="Permalink to &quot;Debugging tests&quot;">​</a></h1><p>If your tests aren&#39;t working as you expect, you can debug them in both the default Node.js environment and in a real browser.</p><h2 id="debugging-in-node-js" tabindex="-1">Debugging in Node.js <a class="header-anchor" href="#debugging-in-node-js" aria-label="Permalink to &quot;Debugging in Node.js&quot;">​</a></h2><p>Debugging in the default Node.js environment is often the quickest way to diagnose issues that are not related to browser-specific APIs or rendering.</p><ol><li>Run the <code>ng test</code> command with the <code>--debug</code> flag:<div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --debug</span></span></code></pre></div></li><li>The test runner will start in debug mode and wait for a debugger to attach.</li><li>You can now attach your preferred debugger. For example, you can use the built-in Node.js debugger in VS Code or the Chrome DevTools for Node.js.</li></ol><h2 id="debugging-in-a-browser" tabindex="-1">Debugging in a browser <a class="header-anchor" href="#debugging-in-a-browser" aria-label="Permalink to &quot;Debugging in a browser&quot;">​</a></h2><p>The same way you start a debugging session with in Node, you can use <code>ng test</code> with the <code>--debug</code> flag with Vitest and <a href="/en/guide/testing/migrating-to-vitest#5-configure-browser-mode-optional">browser mode</a>.</p><p>The test runner will start in debug mode and wait for you to open the browser devtools to debug the tests.</p>',8)]))}const c=t(s,[["render",o]]);export{b as __pageData,c as default};
